def shortest_cycle_length(n, m, edges):
    graph = defaultdict(list)
    for x, y, w in edges:
        graph[x-1].append((y-1, w))
        graph[y-1].append((x-1, w))

    for i in range(n):
        distances = [float('inf')] * n
        distances[i] = 0
        for _ in range(n):
            last_vertices = distances[:]
            for v, _ in enumerate(graph):
                if distances[v] == float('inf'):
                    continue
                for neighbor, w in graph[v]:
                    if distances[neighbor] > distances[v] + w:
                        distances[neighbor] = distances[v] + w
            if all(distance == float('inf') for distance in last_vertices):
                break
        if distances == distances[::-1]:  # Check if a cycle of length n was found
