def is_palindrome(s):
    return s == s[::-1]

def count_crossing_pairs(text):
    n = len(text)
    palindrome_pairs = set()
    for i in range(n):
        for j in range(i, n):
            if is_palindrome(text[i:j+1]):
                left = i
                right = j
                while left >= 0 and right < n and text[left] == text[right]:
                    palindrome_pairs.add((left+1, right+1))
                    left -= 1
                    right += 1
    return palindrome_pairs

def main():
