from collections import defaultdict, deque

def shortest_cycle_length(edges, n):
    graph = defaultdict(list)
    for a, b, w in edges:
        graph[a-1].append((b-1, w))
        graph[b-1].append((a-1, w))

    def bfs(start, visited):
        queue = deque([(start, [start])])
        visited[start] = True
        while queue:
            node, path = queue.popleft()
            for neighbor, weight in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    next_path = path + [neighbor]
                    queue.append((neighbor, next_path))
                    if maximum_weight - weight and len(path) >= 2:
                        return len(path)
                    if maximum_weight - weight <= len(next_path) <= minimum_weight + weight:
                        return len(path) + len(next_path)
        return None

    maximum_weight, minimum_weight = 0, float('inf')
    for i in range(n):
        maximum_weight = max(maximum_weight, len(bfs(i, [False] * n)))
        minimum_weight = min(minimum_weight, len(bfs(i, [False] * n)))

    if minimum_weight == float('inf'):
        return -1
    elif len(edges) < n-1:
        return 0
    else:
        return (maximum_weight - minimum_weight + 2) * len(edges)


