def solve(n, original, goal):
    steps = 0
    prev_flips = set()
    curr_flips = set()
    flipped = False

    while True:
        # Check if original vertices have 'goal' columns
        if all(((v, u % n) in original for (v, u) in goal)):
            break
        if (1, 2) in prev_flips:
            prev_flips.add((2, 1))
            curr_flips.add((2, 1))
        elif (2, 1) in prev_flips:
            prev_flips.remove((2, 1))
            curr_flips.add((2, 1))
        else:
            prev_flips.add((2, 1))
            curr_flips.add((2, 1))
        steps += 1
        if steps >= 20000:
            raise Exception("Exceeded max steps.")

        edge = [0, 0]
        for v, u in prev_flips | curr_flips:
            for d in neighbors(v):
                if d in neighbors(u):
                    edge.append(d)
        edge.sort()
        edge = tuple(edge)
        if edge in prev_flips:
            prev_flips.remove(edge)
            curr_flips.add(edge)
        elif edge in curr_flips:
            prev_flips.add(edge)
            curr_flips.remove(edge)
        else:
            raise Exception("Invalid state reached.")
        if steps % 100 == 0:
            print("Checking flip at step ", steps)
    print(steps)

def neighbors(v):
    for i in range(v + 1, v + n):
        if i >= n: i -= n
        if i % n == v: continue
        u = (i + 1) % n
        if u < v: u = n + u
        yield ((v, u) if v < u else (u, v))

def process():
    n = int(stdin.readline().strip())
    original = [tuple(map(int, line.strip().split())) for line in stdin.readlines()[:n - 3]]
    goal = [tuple(map(int, line.strip().split())) for line in stdin.readlines()[n - 3:]]
    solve(n, original, goal)

