            p_index = 0
            for j in range(n):
                if len(linked_list[j]) == 1:
                    index = linked_list[j][0]
                    invalid = False
                    for tile in linked_list[index]:
                        if perm[tile] not in map and perm[tile] != lis[p_index]:
