from typing import List, Tuple

def recover_array(a1: List[int], b1: List[int], c1: List[int]) -> Tuple[int, ...] | int:
    n = len(a1) + 1
    total_sum = sum(a for a in a1)

    if (total_sum == 0) or (len(set(a1)) != len(a1)):
        return -1

    for i in range(n - 1):
        pairs = [(a1[i] - b1[i], c1[i] - b1[i])]
        pairs.extend([(b1[k] - a1[i], c1[k] - a1[i]) for k in range(i + 1, n)])

        if 0 in [{x // y for (_, y) in pairs}]:
            return -1
        if any(_ < 0 for (_, _) in pairs):
            return -1

    idx = n - 1
    a = [-1] * len(a1)
    stack = [(0, -1)]  # 0: flag, -1: checked before operations
    for row in a1 + b1 + c1:
        if row, idx > stack[-1]:
            a[row] = idx
            idx -= 1
        else:
            while stack and stack[-1][1] < idx and max(stack[-1]) < row:
                stack.pop()
            nxt = stack.pop() if stack else (-1, -1)
            assert nxt > 0
            a[nxt] = idx
            sta = -1
            for i in range(nxt - 1, n):
                non_nxt_params = max([row - a[k] for k in range(nxt))] + [-1]
                sta = max([0] + non_nxt_params)
                idx -= 1

    return tuple(a)

