from collections import defaultdict

def max_distinct_visits(n, m, d, roads, museums):
    graph = defaultdict(list)
    for u, v in roads:
        graph[u-1].append(v-1)

    freq = [0]*n
    visited = [False]*n

    def dfs(start, day):
        nonlocal freq, visited
        if day > d:
            return
        if visited[start]:
            res = list(set(vis) - {start})
            if all([freq[i] == 1 for i in vis]):
                freq[start] = 1
        else:
            res = {start}
        for to in [graph[j] for j in list(res)[::-1]]:
            dfs(start, min(day, d))

    final_res = 0 
    for i in range(n):
        vis = []
        dfs(i, d)
        if all([freq[i] == 1]):
            final_res = max(final_res, len(vis))
    return final_res

