def count_optimal_profiles(n):
    p_count = [n * n for _ in range(n)]
    p_sum = [0] * (n + 1)

    for comb in product(range(n), repeat=2):
        if comb == (0, 1):
            continue

        for total in p_count[:comb[0]][::-1] + p_count[comb[1] + 1:]:
            if comb[0] == comb[1]:
                p_count[comb[0]] -= total
            else:
                p_sum[comb[0]] -= total
                p_sum[comb[1]] += total

    dp = [[] for _ in range(n + 1)]
    p_sum[n] += 1

    for i in range(n, 0, -1):
        cur_count = 0
        for j in range(n - i + 1):
            if j == i:
                for k in range(n):
                    b = j + 1
                    c = n - i
                    dp[j + 1] += product([i] * b, [k] * c)
                continue
            cur_count += 1
            for col in dp[i]:
                d = i + 1
                c = n - d
