        for j in range(1, len(matrix[i])):
            start = end = matrix[i][j-1]
            for k in range(j, len(matrix[i])):
                end = max(end, matrix[i][k])
                if start == end:
                    total_intersection += 1
            if segment_size < start < end:
                count += 1
        if total_intersection <= count:
            segments.append(range(count, total_intersection + count))
            count = 0
    min_segment_size, min_components = float('inf'), float('inf')
    current_segment = 1
    while segments and len(segments) > 1:
        next_segment = min(segments)
        next_i, next_k = min((x for x in next_segment), key=lambda x: x + x % segment_size)
        new_page = next_i + segment_size
        nxt_i, nxt_k = next(i for i in segments[next_i:new_page] if not i.isdisjoint(segments[i:new_page]))
        current_segment += 1
        if nxt_i + nxt_k > min_components:
            min_components, min_segment_size = nxt_i_new_segment, new_segment_size

