from collections import defaultdict
import heapq

def dijkstra(g, src):
    dist = {}
    for v in range(len(g)):
        if v == src:
            dist[v] = 0
        else:
            dist[v] = float('inf')
        pq = [(0, v)]
    while pq:
        d, u = heapq.heappop(pq)
        if u in dist:
            continue
        dist[u] = d
        for v, w in g[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))
    return dist

