def shortest_cycle_length(m: int, start: int) -> int:
    if m < 3:
        return -1

    n = 1 << m  # Binary code for all possible edges

    # Dijkstra's shortest path with weights
    weights = [float('inf') for _ in range(n)]
    weights[start] = 0
    pq = PriorityQueue()
    pq.put((0, start))

