        w, vertex = pq.get()
        for mask, dst, weight in g[vertex]:
            if weight > weights[mask] + w:
                continue
            if mask & (1 << vertex) > 0:
                continue
            else:
                weights[mask] = weight
                pq.put((weight, mask))

    mask = 0
    for w, vertex in g:
        for i, (new_mask, _, _) in enumerate(g[:vertex]):
            cand_mask = mask ^ (1 << vertex)
            cand_mask |= new_mask
            cand_u = 1 << i
            cand_v = cand_mask & (1 << vertex)
            if mask & cand_u == cand_v and cand_u <= m - 1:
                D = w + 1 + weights[cand_mask ^ cand_u ^ cand_v]
                if D < w:
                    return D
            if w != weights[cand_mask]:
                continue
            if weights[cand_mask ^ 1 ^ cand_v] < weights[1 << i] + 1 + weights[1 << i + vertex]:
                return w + 2


