import sys

def flip_diagonal(n, original_edges, matching_edges):
    steps = 0
    visited = set()

    while steps <= 20000:
        for i in range(1, n):
            for j in range(i+1, n):
                if (i, j) in matching_edges or (j, i) in matching_edges:
                    continue
                if not (original_edges[i-1], original_edges[j-1]) in visited:
                    visit_steps(i, j, steps, original_edges, matching_edges, visited)
                    break

def visit_steps(i, j, steps, original_edges, matching_edges, visited):
    if (i, j) in original_edges or (j, i) in original_edges:
        return
    steps += 1
    visited.add((i, j))
    visited.add((j, i))

    original_edges[i-1], matching_edges[(i+1)//2 - 1] = matching_edges[(i+1)//2 - 1], original_edges[i-1]
    print(f"{i} {j}")
    return

