def find_cross_pairs(text):
    n = len(text)
    palindrome_pairs = [[0] * n for _ in range(n)]
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1
    for i in range(1, n):
        if text[i - 1] == text[i]:
            dp[i][i] = 1
    for length in range(2, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            if text[start] == text[end]:
                dp[start][end] = dp[start + 1][end - 1]
            for mid in range(start + 1, end):
                palindrome_pairs[start][end] += dp[start][mid] * dp[mid][end]
                palindrome_pairs[start][end] %= 51123987
    return palindrome_pairs[0][n - 1]

