def dijkstra(g: List[List[Tuple[int, int]]], start: int) -> Tuple[int, List[List[Tuple[int, int]]]]:
    # Initialize the shortest path distances and the predecessors for the vertices
    n = len(g)
    dist = [float('inf')] * n
    prev = [-1] * n
    dist[start] = 0
    prev[start] = start
    # Use a priority queue (min-heap) to keep track of the vertices to process
    pq = [(0, start)]
    while pq:
        (d, u) = heapq.heappop(pq)
        if d > dist[u]:
