            dje = (ystart(p[k], p[k + 1]).y > y[k])
            different_j = xs[l][1] > xs[l + 1][1] or dje
        if obtained:
            if len(xs[l]) == 1 or (x0 > xs[l][1] and y0 > ys[l]) or (x0 < xs[l][1] and y0 <= ys[l]):
                most_right = True
    if most_right:
