MOD = int(1e9 + 7)

def find_fixed_point(b):
    def binary_search(left, find_fixed_point_func):
        x = 0
        while left <= b:
            mid = (left + b) // 2
            if find_fixed_point_func(mid) >= mid:
                left = mid + 1
            else:
                x = mid
                b = mid - 1
        return x

    left, right = 0, b + 1
    x = binary_search(left, lambda m: m * (m + 1) // 2)
    return x

def combinations(nums, size):
    n = len(nums)
    if size > n:
        return 0
    if size == n or size == 0:
        return 1

    result = 1
    for i in range(size, n):
        result *= nums[i]
        result %= MOD
    return result

def fast_wqf(N):
    return find_fixed_point(N)

def one_pass_operations(N, S):
    b = find_fixed_point(N)
    return combinations(b, one_pass_operations(N, one_pass_operations(S, find_fixed_point(b))))

def main():
    N = int(input())
    S = list(map(lambda x: int(x), input().split()))

    # Iterate through each input
    for i in range(200):
        one_pass_operations(N, S)

if __name__ == "__main__":
    main()
