import sys
import collections

def find_articulation_points_and_bridges(n, adj_list):
    cycle, articulation_points, visited, low, disc, time = [False] * (n + 2), [], [False] * n, [False] * n, [float('inf')] * n, 0

    def dfs(u, p):
        disc[u] = low[u] = time
        time += 1

        visited[u] = True
        children = 0
        components = 0

        for v in adj_list[u]:
            if not visited[v]:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                children += 1

                if p != v:
                    if (disc[v] <= low[u]) and (disc[v] <= disc[u]):
                        cycle.append(v)
                        articulation_points.append(u)
                    if low[v] > disc[u]:
                        if u != p:
                            if len(cycle) > 1 and components > 1:
                                articulation_points.append(u)
            elif v != p:
                low[u] = min(low[u], low[v])

        if p != u and len(cycle) > 1 and children > 1:
            articulation_points.append(u)

    visited = [False] * n

    for i in range(n):
        if not visited[i]:
            dfs(i, -1)

    return cycle, articulation_points, low


def main():
    input_lines = sys.stdin.read().splitlines()
    n, m = map(int, input_lines[0].split())
    adj_list = [[] for _ in range(n + 2)]
    for _ in range(m):
        u, v = map(int, input_lines[1 + _].split())
        adj_list[u].append(v)
        adj_list[v].append(u)

    cycle, articulation_points, _ = find_articulation_points_and_bridges(n, adj_list)

    queries = int(input_lines[n + m + 1])
    for _ in range(queries):
        cycle_len, *vertexes = map(int, input_lines[n + m + 2 + _].split())
        answer = 0
        for vertex in vertexes:
            if any(vertex == u or vertex == v for u, v in zip(cycle, cycle) if u != v):
                answer += 1
        print(answer)


if __name__ == "__main__":
    main()
