from typing import List

def is_unique_solution(tiles: List[str]) -> bool:
    n = len(tiles)
    for i in range(n):
        for j in range(n):
            if tiles[i][j] == '.' and (i + 1 < n and tiles[i + 1][j] == tiles[i][j]) or (j + 1 < n and tiles[i][j + 1] == tiles[i][j]):
                return False
    return True

def tile_choices(tiles: List[str], i: int, j: int) -> List[List[str]]:
    if i + 1 < n and tiles[i + 1][j] == tiles[i][j]:
        return [["S", "G"]] if tiles[i][j] == "." else
                [["S"], ["G"], ["S"], ["G"], ["S"], ["G"], ["S"], ["G"], ["S"], ["G"]]
    elif j + 1 < n and tiles[i][j + 1] == tiles[i][j]:
        return [["G"], ["S"], ["S"], ["G"], ["G"], ["S"], ["S"], ["G"], ["S"], ["G"]] if tiles[i][j] == "." else
                [["G"], ["S"], ["G"], ["S"], ["G"], ["S"], ["S"], ["G"], ["S"], ["G"]]
    else:
        return [["."], ["."], ["."], ["."], ["."], ["."], ["."], ["."], ["."], ["."]]

def find_unique_solution(input_tiles: List[str]) -> None:
    n = len(input_tiles)
    seen = set()
    for i in range(n):
        for j in range(n):
            if (i, j) not in seen:
                possible_choices = tile_choices(input_tiles, i, j)
                if all(nr == '' for nr in [*possible_choices[0], *possible_choices[-1]]):
                    seen.add((i, j))
                    for index, choice in enumerate(possible_choices):
                        if choice[0] != 'S':
                            possible_choices[index] = ['?'].extend(choice[1:])
                        if choice[0] != 'G':
                            possible_choices[index] = ['?'].extend(choice[1:])
                    if is_unique_solution(possible_choices):
                        print('UNIQUE')
                        for pos in possible_choices:
                            print(''.join(pos))
                        break

