from collections import defaultdict
import sys

n, m = map(int, input().split())
graph = defaultdict(list)
for _ in range(m):
    u, v, w = map(int, input().split())
    graph[u-1].append((v-1, w))
    graph[v-1].append((u-1, w))

def dijkstra(start, end, graph):
    dist = {x: float('inf') for x in range(n)}
    dist[start] = 0
    pq = [(0, start)]
    while pq:
        cur_dist, cur_node = heapq.heappop(pq)
        if cur_node == end:
            return cur_dist, dist
        if cur_dist > dist[cur_node]:
            continue
        for next_node, weight in graph[cur_node]:
            new_dist = cur_dist + weight
            if new_dist < dist[next_node]:
                dist[next_node] = new_dist
                heapq.heappush(pq, (new_dist, next_node))
    return float('inf'), dist

def find_cycle(start, use_cyclic_path=False):
    min_distance, _ = dijkstra(0, start, graph)
    if min_distance == float('inf'):
        return -1
    else:
        dist = {[0] + [min_distance] + [sys.maxsize] * (n-1)}
        visited = set()
        stack = [(None, 0)]
        visited.add(0)
        while stack:
            prev, cur = stack.pop()
            if cur in visited:
                continue
            visited.add(cur)
            if cur == start:
                return min_distance
            for node, weight in graph[cur]:  
                if weight > 1:
                    stack.append((cur, node))
                    dist[cur].append(1)
                    dist[cur].append(0)
                else:
                    if node != start and not use_cyclic_path:
                        reachable = next(cur if (node, weight) in graph and dist[node][weight+1]<sys.maxsize else (cur-1) for node in range(n) if not visited)
                    else:
                        reachable = next((cur-1, node-1) for node in range(n) if not visited and (node, weight) in graph)
                    stack.append(reachable)
                    dist[cur].append(weight)
                    dist[cur].append(reachable[1])
                dist[node].append(0)
        return sum(d for s in dist for d in s) - dist[start][start+1]


cycle_length = find_cycle(0)
print(-1 if cycle_length == float('inf') else cycle_length)
